    #[test]
    fn differential_vs_cpp() {
        assert!(!CASES.is_empty());
        for (i, (pts, s, d0, d1, a, want)) in CASES.iter().enumerate() {
            let p: Vec<[f64; 3]> = pts.iter().map(|&(x, y, z)| [x, y, z]).collect();
            assert_eq!(detect_corners(&p, *s, *d0, *d1, *a), *want, "case {i}");
        }
    }
